-- =============================================================================
-- NFS-e: dados da reforma tributária (IBS/CBS) por serviço
--
-- O leiaute da NT 009 v1.01 (já validado na produção restrita) exige, para
-- competência a partir de 01/10/2026, o grupo IBSCBS com o código NBS do
-- serviço, o indicador da operação (cIndOp) e a classificação tributária
-- (CST/cClassTrib); para o Simples ME/EPP, também a atividade do Simples
-- (cAtvSN). A tabela oficial de correlação (Anexo VIII v1.01.00 da
-- documentação RTC: item da LC 116 × NBS × cIndOp × cClassTrib) fica aqui
-- para o escritório escolher e para conferir o que for salvo.
-- =============================================================================

create table public.nfse_correlacao_ibscbs (
  item text not null check (item ~ '^[0-9]{2}\.[0-9]{2}(\.[0-9]{2})?$'),
  nbs text not null check (nbs ~ '^[0-9]{9}$'),
  descricao_nbs text not null,
  cind_op text not null check (cind_op ~ '^[0-9]{6}$'),
  cclass_trib text not null check (cclass_trib ~ '^[0-9]{6}$'),
  nome_cclass_trib text not null,
  primary key (item, nbs, cind_op, cclass_trib)
);
comment on table public.nfse_correlacao_ibscbs is
  'Correlação item da LC 116 × NBS × cIndOp × cClassTrib (Anexo VIII v1.01.00, documentação RTC da NFS-e).';

alter table public.nfse_correlacao_ibscbs enable row level security;
create policy nfse_correlacao_ibscbs_leitura on public.nfse_correlacao_ibscbs for select to authenticated using (true);
revoke all on public.nfse_correlacao_ibscbs from anon, authenticated;
grant select on public.nfse_correlacao_ibscbs to authenticated;


-- Indicador da operação, classificação do IBS/CBS e atividade do Simples (cAtvSN) de cada serviço
alter table public.nfse_servicos
  add column cind_op text check (cind_op is null or cind_op ~ '^[0-9]{6}$'),
  add column cclass_trib text check (cclass_trib is null or cclass_trib ~ '^[0-9]{6}$'),
  add column atividade_sn smallint check (atividade_sn is null or atividade_sn in (7, 8, 9, 10, 11, 12, 13, 14, 90));
alter table public.nfse_emissoes
  add column cind_op text check (cind_op is null or cind_op ~ '^[0-9]{6}$'),
  add column cclass_trib text check (cclass_trib is null or cclass_trib ~ '^[0-9]{6}$'),
  add column atividade_sn smallint check (atividade_sn is null or atividade_sn in (7, 8, 9, 10, 11, 12, 13, 14, 90));

-- Itens da tabela de correlação de um código de tributação: subitem (14.10) e, no item 99, o código completo (99.04.01)
create or replace function app.nfse_itens_correlacao(p_codigo text)
returns text[]
language sql
immutable
set search_path = ''
as $$
  select array[substr(p_codigo, 1, 2) || '.' || substr(p_codigo, 3, 2),
               substr(p_codigo, 1, 2) || '.' || substr(p_codigo, 3, 2) || '.' || substr(p_codigo, 5, 2)];
$$;

-- A nota guarda os dados do serviço como estavam no pedido
create or replace function app.tg_nfse_emissao_reforma()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.servico_id is not null then
    select coalesce(new.codigo_nbs, s.codigo_nbs), coalesce(new.cind_op, s.cind_op), coalesce(new.cclass_trib, s.cclass_trib),
           coalesce(new.atividade_sn, s.atividade_sn)
      into new.codigo_nbs, new.cind_op, new.cclass_trib, new.atividade_sn
      from public.nfse_servicos s
     where s.id = new.servico_id;
  end if;
  return new;
end;
$$;
create trigger nfse_emissoes_reforma before insert on public.nfse_emissoes
  for each row execute function app.tg_nfse_emissao_reforma();

create or replace function public.nfse_servico_salvar(p_empresa_id uuid, p_id uuid, p_dados jsonb)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_codigo text := p_dados ->> 'codigo_tributacao_nacional';
  v_nbs text := nullif(p_dados ->> 'codigo_nbs', '');
  v_indop text := nullif(p_dados ->> 'cind_op', '');
  v_class text := nullif(p_dados ->> 'cclass_trib', '');
  v_ativ smallint := nullif(p_dados ->> 'atividade_sn', '')::smallint;
  v_itens text[];
begin
  perform app.exigir(p_empresa_id, 'nfse.configurar');
  if not exists (select 1 from public.nfse_lista_servicos where codigo = v_codigo) then
    raise exception 'O código % não está na lista nacional de serviços. Escolha o serviço pela busca.', coalesce(v_codigo, '(vazio)')
      using errcode = '22023';
  end if;
  v_itens := app.nfse_itens_correlacao(v_codigo);

  -- NBS e classificação do IBS/CBS conferidos na tabela oficial (quando ela traz o serviço)
  if v_nbs is not null and exists (select 1 from public.nfse_correlacao_ibscbs where item = any(v_itens)) then
    if not exists (select 1 from public.nfse_correlacao_ibscbs where item = any(v_itens) and nbs = v_nbs) then
      raise exception 'O código NBS informado não corresponde a este serviço na tabela oficial da reforma tributária.' using errcode = '22023';
    end if;
    if v_indop is null or v_class is null then
      select c.cind_op, c.cclass_trib into v_indop, v_class
        from public.nfse_correlacao_ibscbs c
       where c.item = any(v_itens) and c.nbs = v_nbs
       order by (c.cind_op like '%01') desc, (c.cclass_trib = '000001') desc, c.cind_op, c.cclass_trib
       limit 1;
    elsif not exists (select 1 from public.nfse_correlacao_ibscbs
                       where item = any(v_itens) and nbs = v_nbs and cind_op = v_indop and cclass_trib = v_class) then
      raise exception 'A classificação do IBS/CBS escolhida não corresponde a este NBS na tabela oficial.' using errcode = '22023';
    end if;
  elsif (v_indop is null) <> (v_class is null) then
    raise exception 'Informe juntos o indicador da operação e a classificação do IBS/CBS.' using errcode = '22023';
  end if;

  -- Atividade do Simples: as que a NT 009 liga a serviços específicos valem só para eles (e eles só aceitam essas)
  if v_ativ is not null then
    if (substr(v_codigo, 1, 4) = '1601') <> (v_ativ = 10)
       or (v_codigo = '990401') <> (v_ativ = 11)
       or (substr(v_codigo, 1, 4) in ('0702', '0705')) <> (v_ativ in (12, 13)) then
      raise exception 'A atividade do Simples escolhida não combina com este serviço.' using errcode = '22023';
    end if;
  end if;

  if p_id is null then
                                      cind_op, cclass_trib, atividade_sn)
    values (p_empresa_id, trim(p_dados ->> 'nome'), v_codigo,
            nullif(p_dados ->> 'codigo_tributacao_municipal', ''), v_nbs,
            nullif(trim(p_dados ->> 'descricao_padrao'), ''), coalesce((p_dados ->> 'ativo')::boolean, true),
            nullif(p_dados ->> 'cnae', ''), v_indop, v_class, v_ativ)
    returning id into v_id;
  else
    update public.nfse_servicos
       set nome = trim(p_dados ->> 'nome'),
           codigo_tributacao_nacional = v_codigo,
           codigo_tributacao_municipal = nullif(p_dados ->> 'codigo_tributacao_municipal', ''),
           codigo_nbs = v_nbs,
           descricao_padrao = nullif(trim(p_dados ->> 'descricao_padrao'), ''),
           ativo = coalesce((p_dados ->> 'ativo')::boolean, true),
           cnae = nullif(p_dados ->> 'cnae', ''),
           cind_op = v_indop,
           cclass_trib = v_class,
           atividade_sn = v_ativ
     where id = p_id and empresa_id = p_empresa_id
    returning id into v_id;
    if v_id is null then
      raise exception 'Serviço não encontrado.';
    end if;
  end if;
  return v_id;
end;
$$;
